this.uiLanguageAndLocale$
            .pipe(
                take(1),
                switchMap(([currentLanguage, currentLocale]) => {
                    return this.modalService.fromComponent(UiLanguageSwitcherDialogComponent, {
                        closable: true,
                        size: 'lg',
                        locals: {
                            availableLocales: this.availableLocales,
                            availableLanguages: this.availableLanguages,
                            currentLanguage: currentLanguage,
                            currentLocale: currentLocale,
                        },
                    });
                }),
                switchMap(result =>
                    result ? this.dataService.client.setUiLanguage(result[0], result[1]) : EMPTY,
                ),
            ).subscribe

timer(delay)
            .pipe(
                switchMap(() => this.dataService.client.userStatus().mapSingle(data => data.userStatus)),
                switchMap(userStatus => {
                    if (userStatus.permissions.includes(Permission.ReadSettings) && userStatus.isLoggedIn) {
                        return this.dataService.settings.getRunningJobs().single$;
                    } else {
                        return EMPTY;
                    }
                }),
            ).subscribe

